import { describe, expect, it } from 'vitest';
import { testCall } from './testCall';
import { newProject, type Mock, type Project } from './types';

function mock(id: string, urlPattern: string, extra: Partial<Mock> = {}): Mock {
  return {
    id,
    name: id,
    enabled: true,
    method: 'GET',
    urlPattern,
    response: { status: 200, headers: {}, body: id, bodyEncoding: 'text', delayMs: 0 },
    source: 'manual',
    createdAt: 0,
    ...extra,
  };
}

function project(): Project {
  const p = newProject('p1', 'http://app.test');
  p.scenarios[0]!.mocks.push(mock('doc-1', '/doc/1'), mock('doc-any', '/doc/:id'), mock('off', '/off', { enabled: false }));
  p.scenarios.push({ id: 'empty', name: 'Empty list', mocks: [mock('doc-empty', '/doc/:id')] });
  return p;
}

describe('testCall (A3)', () => {
  it('resolves a relative URL against the page origin and finds the first match', () => {
    const r = testCall(project(), { method: 'GET', url: '/doc/1?x=1' }, 'http://app.test');
    expect(r).toEqual({ ok: true, url: 'http://app.test/doc/1?x=1', mock: expect.objectContaining({ id: 'doc-1' }), scenarioName: 'Default' });
  });

  it('uses the active scenario first, then Default, like the page', () => {
    const p = { ...project(), activeScenarioId: 'empty' };
    const r = testCall(p, { method: 'GET', url: '/doc/1' }, 'http://app.test');
    expect(r.ok && r.mock?.id).toBe('doc-empty');
    expect(r.ok && r.scenarioName).toBe('Empty list');
  });

  it('reports no match: a disabled mock, another method, or no pattern', () => {
    for (const input of [
      { method: 'GET', url: '/off' },
      { method: 'POST', url: '/doc/1' },
      { method: 'GET', url: '/nothing' },
    ]) {
      const r = testCall(project(), input, 'http://app.test');
      expect(r).toMatchObject({ ok: true, mock: null, scenarioName: null });
    }
  });

  it('keeps an absolute URL as typed, so a host-bound pattern can match', () => {
    const p = project();
    p.scenarios[0]!.mocks.unshift(mock('api', 'https://api.test/doc/:id'));
    const r = testCall(p, { method: 'get', url: 'https://api.test/doc/5' }, 'http://app.test');
    expect(r.ok && r.url).toBe('https://api.test/doc/5');
    expect(r.ok && r.mock?.id).toBe('api');
  });

  it('passes the body to matching, for GraphQL operations', () => {
    const p = project();
    p.scenarios[0]!.mocks.unshift(mock('gql', '/graphql', { method: 'POST', graphqlOperation: 'GetUser' }));
    const hit = testCall(p, { method: 'POST', url: '/graphql', body: '{"operationName":"GetUser"}' }, 'http://app.test');
    const miss = testCall(p, { method: 'POST', url: '/graphql', body: '{"operationName":"Other"}' }, 'http://app.test');
    expect(hit.ok && hit.mock?.id).toBe('gql');
    expect(miss.ok && miss.mock).toBeNull();
  });

  it('rejects an empty or unparseable URL', () => {
    expect(testCall(project(), { method: 'GET', url: '   ' }, 'http://app.test')).toEqual({ ok: false, error: 'Type a URL' });
    expect(testCall(project(), { method: 'GET', url: 'http://' }, 'http://app.test')).toEqual({ ok: false, error: 'Not a valid URL' });
    expect(testCall(project(), { method: 'GET', url: '/a' }, '')).toEqual({ ok: false, error: 'Not a valid URL' });
  });
});
